{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, an ester prodrug, has only 15% oral bioavailability in humans, providing affirmative evidence that an ester prodrug can fall below the 20% threshold; although its polar framework differs from the query, it supports the low-absorption direction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "DINCH, a highly lipophilic dialkyl ester, is almost completely bioavailable in humans, showing that lipophilic esters can be well absorbed; however, it lacks the beta-lactone ring and GI-localized lipase-inhibitor design of the query, so its transferability is low.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "DVAS, a dodecyl ester dipeptide, has about 60% oral bioavailability in healthy volunteers, another example of a lipophilic ester being absorbed; it lacks the beta-lactone warhead and is not structurally transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an orlistat-like beta-lactone (N-formyl-L-leucine ester of a 3-hexyl-4-alkyl-2-oxetanone). Orlistat and related beta-lactone lipase inhibitors are designed to act in the GI lumen and have negligible systemic oral bioavailability. The retrieved high-F ester analogues lack the reactive beta-lactone and are not transferable; the only low-F record supports the possibility of low absorption. Therefore predict low (F < 20%).",
  "evidence_gaps": [
    "No direct orlistat or beta-lactone analogue with measured oral bioavailability was retrieved; all retrieved analogues are simple esters/prodrugs with low structural similarity.",
    "The only low-F record (laninamivir octanoate) has a polar framework that is not representative of the query's highly lipophilic beta-lactone."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "low",
      "card_ids": ["C16", "C12"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "lipophilic ester oral bioavailability"
    }
  ],
  "revision_action": "initial"
}

